test:
def test_filters_heavier_than_limit():
    pallets = [{'id': 'A', 'weight': 500}, {'id': 'B', 'weight': 1200}, {'id': 'C', 'weight': 900}]
    assert heavy_pallet_ids(pallets, 800) == ['B', 'C'], 'must return ids of pallets heavier than the limit, in order'

def test_weight_equal_to_limit_is_excluded():
    pallets = [{'id': 'A', 'weight': 800}]
    assert heavy_pallet_ids(pallets, 800) == [], 'a pallet exactly at the limit is not "over" it, so it must be excluded'

def test_empty_pallet_list():
    assert heavy_pallet_ids([], 100) == [], 'no pallets means an empty result'
